 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # A color key is a short row repeated vertically (one occurrence per color).
    key = None
    for r in range(h - 1):
        for c0 in range(w):
            for c1 in range(c0 + 2, w + 1):
                seq = grid[r][c0:c1]
                if 0 not in seq and len(set(seq)) == len(seq) and grid[r + 1][c0:c1] == seq:
                    r1 = r + 2
                    while r1 < h and grid[r1][c0:c1] == seq:
                        r1 += 1
                    if r1 - r >= 2 and (key is None or len(seq) > len(key)):
                        key = seq[:]
    if key is None or 1 not in key:
        return [row[:] for row in grid]

    # Select the largest 4-connected color-1 object, excluding isolated key marks.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    motif = max(components, key=len)
    top = min(r for r, _ in motif)
    left = min(c for _, c in motif)
    mh = max(r for r, _ in motif) - top + 1
    offsets = [(r-top, c-left) for r,c in motif]
    start = top - key.index(1) * mh

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(key):
        for dr, dc in offsets:
            rr, cc = start + i*mh + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
